"""Freeze the worker source snapshot and review full local call/page composition."""
import hashlib,json,shutil,subprocess,time
from pathlib import Path
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
S=ROOT/'work/mac-poseidon-width3-call10/review-snapshot01';F=H/'frozen'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(S/'manifest.json')=='5e4ac8e698deaa46b29ed7e9f57d63d4ece5ff73a2a25936fa4c1e84c74992e3'
m=json.loads((S/'manifest.json').read_text());assert not F.exists();F.mkdir()
for x in m['files']:
    src=S/x['path'];assert sha(src)==x['sha256'] and src.stat().st_size==x['bytes']
    dst=F/x['path'];dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dst)
shutil.copyfile(S/'manifest.json',F/'manifest.json')
prompt=f'''Review immutable whole width3 domain-18 arity-one call/page source snapshot at {F}, read-only Read/Glob/Grep, no code execution, builds, or edits. Prior independent Opus5.5 prefix review found no math defect; its two provenance issues were a parent snapshot omission of generate_absorption_probe.py (now included) and an incorrect attribution header naming generate_absorption.py. Worker preserves the accepted closure and a separate regenerated attribution successor; inspect header issue as known historical metadata, no request to alter accepted proof bytes. Focus CompilerSequenceCompletion, PoseidonSuffixComposition10, CompilerPageSelectionPosition10, WholeCall10Proof01/Page01 and their maintained generators/templates, Prefix10Controls01 and WholeCall10PageControls01. Check rounds0/1 prefix composed with accepted rounds2..64 suffix under the SAME final rho, independent hash3 domain18/input list length1/zero pad/result word1. Constructor238steps =12prefixmaterialized+225suffixmaterialized+singlecopy,317rows=16prefix+300suffix+singlecopy, capture rows38876..39191+copy200769. Writes within[61614,61930), preservation outside actualwrite interval, original22735inputs at3+input, zero/copy and inputLCcut363983. Prefix support does not overlap suffix writes. Prior page rows38400..38875 count476 preserved CONDITIONALLY on base satisfaction and checked outside support. Later page rows39192..39423 are not claimed preserved or completed. fullRows names a local page38400..39423+copy only, not full200770 relation. Verify exact positional selected row/capture index theorem, checked inclusion from local page, checker length and zipped positional consistency. Field/CharP p, rho0=1,4!=0,copylinked are explicit. Upstream cut/input construction, raw/native correspondence, full global frame/all210 permutations/fullTransfer remain OPEN. Parent data comparison checked exact44nodes26constants17prefixrows and suffixboundary; prior suffix/page data already independently reviewed. Parent will reparse current complete pp.all and axioms separately. Controls prove finite checked guards; do not infer semantic inequality or injectivity or native correspondence from a rejected guard. Check count/round/state errors, source-vs-target renaming orientation, hidden base equality, quantifier/frame mistakes, unsupported closure, and maintained generator provenance. Also review newly included generate_absorption_probe.py against the previous frozen prefix declarations to resolve parent omission. Report actionable defects with evidence or no defect in the exact whole local call/page scope.'''
(H/'review-prompt.txt').write_text(prompt+'\n');started=time.monotonic()
cmd=['/Users/antoinecyr/.local/bin/claude','--model','claude-opus-5-5','--effort','high','--permission-mode','plan','--tools','Read,Glob,Grep','--strict-mcp-config','--no-session-persistence','--output-format','json','--print',prompt]
with (H/'opus55-review.json').open('w') as out,(H/'opus55-review.stderr').open('w') as err:r=subprocess.run(cmd,stdout=out,stderr=err,timeout=900)
j=json.loads((H/'opus55-review.json').read_text());assert r.returncode==0 and not j['is_error'] and 'claude-opus-5-5' in j['modelUsage']
assert all(sha(F/x['path'])==x['sha256'] for x in m['files'])
print(json.dumps({'review':'complete','files':len(m['files']),'seconds':time.monotonic()-started,'model':list(j['modelUsage'])}))
